const http = require('http');

const testCases = [
  {
    name: 'Missing name field',
    body: { email: 'test@example.com' },
    expectedStatus: 400,
    expectedError: 'Missing required field: name'
  },
  {
    name: 'Name is null',
    body: { name: null },
    expectedStatus: 400,
    expectedError: 'Missing required field: name'
  },
  {
    name: 'Name is number (non-string)',
    body: { name: 123 },
    expectedStatus: 400,
    expectedError: 'Invalid data type: name must be a string'
  },
  {
    name: 'Name is boolean (non-string)',
    body: { name: true },
    expectedStatus: 400,
    expectedError: 'Invalid data type: name must be a string'
  },
  {
    name: 'Name is empty string',
    body: { name: '' },
    expectedStatus: 400,
    expectedError: 'Invalid value: name cannot be empty'
  },
  {
    name: 'Name is whitespace only',
    body: { name: '   ' },
    expectedStatus: 400,
    expectedError: 'Invalid value: name cannot be empty'
  },
  {
    name: 'Valid request',
    body: { name: 'Charlie' },
    expectedStatus: 201,
    expectedError: null
  }
];

console.log('Test cases for POST /users validation:\n');

testCases.forEach((testCase, index) => {
  console.log(`Test ${index + 1}: ${testCase.name}`);
  console.log(`Request body: ${JSON.stringify(testCase.body)}`);
  console.log(`Expected status: ${testCase.expectedStatus}`);
  if (testCase.expectedError) {
    console.log(`Expected error: "${testCase.expectedError}"`);
  }
  console.log('---');
});

