// Simple test script to verify POST validation works
const app = require('./app.js');
const request = require('supertest');

// Test the POST endpoint with various validation scenarios
async function testPostValidation() {
  console.log('Testing POST /users validation...\n');

  // Test 1: Missing name field
  console.log('Test 1: Missing name field');
  const response1 = await request(app).post('/users').send({ email: 'test@example.com' });
  console.log(`Status: ${response1.status}, Response: ${JSON.stringify(response1.body)}`);
  console.log(`Expected: 400 with 'Missing required field: name'`);
  console.log(`Result: ${response1.status === 400 && response1.body.error === 'Missing required field: name' ? '✓ PASS' : '✗ FAIL'}\n`);

  // Test 2: Name is not a string (number)
  console.log('Test 2: Name is a number');
  const response2 = await request(app).post('/users').send({ name: 123 });
