// Simple test script to verify POST validation
const http = require('http');

const testCases = [
  {
    name: 'Missing name field',
    data: { email: 'test@example.com' },
    expectedStatus: 400,
    expectedMessage: 'Missing required field: name'
  },
  {
    name: 'Non-string name',
    data: { name: 123 },
    expectedStatus: 400,
    expectedMessage: 'Field "name" must be a string'
  },
  {
    name: 'Empty name string',
    data: { name: '' },
    expectedStatus: 400,
    expectedMessage: 'Field "name" cannot be empty or whitespace only'
  },
  {
    name: 'Whitespace-only name',
    data: { name: '   ' },
    expectedStatus: 400,
    expectedMessage: 'Field "name" cannot be empty or whitespace only'
  },
  {
    name: 'Valid name',
    data: { name: 'John Doe' },
    expectedStatus: 201,
    expectedMessage: 'User created successfully'
  }
];

function runTest(testCase) {
  return new Promise((resolve) => {
    const postData = JSON.stringify(testCase.data);

    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/users',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        const result = JSON.parse(data || '{}');
        resolve({
          testCase: testCase.name,
          expectedStatus: testCase.expectedStatus,
          actualStatus: res.statusCode,
          expectedMessage: testCase.expectedMessage,
          actualMessage: result.message || result.error,
          passed: res.statusCode === testCase.expectedStatus && 
                  (result.message === testCase.expectedMessage || 
                   result.message?.includes(testCase.expectedMessage))
        });
      });
    });

    req.on('error', (e) => {
      resolve({
        testCase: testCase.name,
        error: e.message,
        passed: false
      });
    });

    req.write(postData);
    req.end();
  });
}

async function runAllTests() {
  console.log('Starting validation tests...\n');

  for (const testCase of testCases) {
    const result = await runTest(testCase);

    if (result.passed) {
      console.log(`✅ ${result.testCase}: PASSED`);
    } else {
      console.log(`❌ ${result.testCase}: FAILED`);
      console.log(`   Expected: ${result.expectedStatus} - ${result.expectedMessage}`);
      console.log(`   Got: ${result.actualStatus} - ${result.actualMessage}`);
    }
  }

  console.log('\nTests completed.');
}

runAllTests().catch(console.error);

