const request = require('supertest');
const app = require('../app');

describe('User API', () => {
  describe('GET /health', () => {
    it('should return health status', async () => {
      const response = await request(app).get('/health');
      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('status', 'ok');
      expect(response.body).toHaveProperty('timestamp');
    });
  });

  describe('GET /users', () => {
    it('should return list of users', async () => {
      const response = await request(app).get('/users');
      expect(response.status).toBe(200);
      expect(Array.isArray(response.body)).toBe(true);
      expect(response.body.length).toBeGreaterThan(0);
      expect(response.body[0]).toHaveProperty('id');
      expect(response.body[0]).toHaveProperty('name');
      expect(response.body[0]).toHaveProperty('email');
    });
  });

  describe('POST /users', () => {
    it('should create a new user with valid name', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: 'John Doe' });

      expect(response.status).toBe(201);
      expect(response.body).toHaveProperty('message', 'User created successfully');
      expect(response.body.user).toHaveProperty('id');
      expect(response.body.user).toHaveProperty('name', 'John Doe');
      expect(response.body.user).toHaveProperty('email');
      expect(response.body.user).toHaveProperty('createdAt');
    });

    it('should return 400 when name is missing', async () => {
      const response = await request(app)
        .post('/users')
        .send({});

      expect(response.status).toBe(400);
      expect(response.body).toHaveProperty('error', 'Missing required field: name');
    });

    it('should return 400 when name is null', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: null });

      expect(response.status).toBe(400);
      expect(response.body).toHaveProperty('error', 'Missing required field: name');
    });

    it('should return 400 when name is not a string', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: 123 });

      expect(response.status).toBe(400);
      expect(response.body).toHaveProperty('error', 'Invalid data type: name must be a string');
    });

    it('should return 400 when name is empty string', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: '' });

      expect(response.status).toBe(400);
      expect(response.body).toHaveProperty('error', 'Invalid value: name cannot be empty or whitespace only');
    });

    it('should return 400 when name is whitespace only', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: '   ' });

      expect(response.status).toBe(400);
      expect(response.body).toHaveProperty('error', 'Invalid value: name cannot be empty or whitespace only');
    });

    it('should trim whitespace from name', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: '  Jane Smith  ' });

      expect(response.status).toBe(201);
      expect(response.body.user).toHaveProperty('name', 'Jane Smith');
    });
  });
});

