// Verification script for deployment structure
const fs = require('fs');

console.log('=== Deployment Structure Verification ===\n');

const requiredFiles = [
  'app.js',
  'package.json',
  'README.md',
  '.gitignore',
  'Dockerfile',
  'docker-compose.yml',
  'Makefile',
  'DEPLOYMENT.md'
];

const testFiles = [
  'test/app.test.js'
];

let allGood = true;

// Check required files
console.log('Required Files:');
requiredFiles.forEach(file => {
  const exists = fs.existsSync(file);
  console.log(`${exists ? '✓' : '✗'} ${file}`);
  if (!exists) allGood = false;
});

console.log('\nTest Files:');
testFiles.forEach(file => {
  const exists = fs.existsSync(file);
  console.log(`${exists ? '✓' : '✗'} ${file}`);
  if (!exists) allGood = false;
});

// Check app.js contents
console.log('\nApp.js Validation:');
try {
  const appContent = fs.readFileSync('app.js', 'utf8');

  const checks = [
    { name: 'Has express import', check: appContent.includes("const express = require('express')") },
    { name: 'Has JSON middleware', check: appContent.includes('app.use(express.json())') },
    { name: 'Has POST /users endpoint', check: appContent.includes('app.post(\'/users\'') },
    { name: 'Has missing name validation', check: appContent.includes('Missing required field: name') },
    { name: 'Has non-string validation', check: appContent.includes('name must be a string') },
    { name: 'Has empty string validation', check: appContent.includes('name cannot be empty or whitespace only') }
  ];

  checks.forEach(({name, check}) => {
    console.log(`${check ? '✓' : '✗'} ${name}`);
    if (!check) allGood = false;
  });
} catch (err) {
  console.log('✗ Cannot read app.js:', err.message);
  allGood = false;
}

// Check package.json
console.log('\nPackage.json Validation:');
try {
  const packageJson = JSON.parse(fs.readFileSync('package.json', 'utf8'));

  const checks = [
    { name: 'Has main entry', check: packageJson.main === 'app.js' },
    { name: 'Has start script', check: packageJson.scripts && packageJson.scripts.start },
    { name: 'Has express dependency', check: packageJson.dependencies && packageJson.dependencies.express },
    { name: 'Has test script', check: packageJson.scripts && packageJson.scripts.test },
    { name: 'Has Node.js engine', check: packageJson.engines && packageJson.engines.node }
  ];

  checks.forEach(({name, check}) => {
    console.log(`${check ? '✓' : '✗'} ${name}`);
    if (!check) allGood = false;
  });
} catch (err) {
  console.log('✗ Cannot parse package.json:', err.message);
