const request = require('supertest');
const app = require('../app');

describe('POST /users input validation', () => {
  test('should reject request with missing name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ email: 'test@example.com' });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Missing required field: name');
  });

  test('should reject request with null name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: null });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Missing required field: name');
  });

  test('should reject request with non-string name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Field "name" must be a string');
  });

  test('should reject request with empty string name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '' });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Field "name" cannot be empty or whitespace only');
  });

  test('should reject request with whitespace-only name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '   ' });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Field "name" cannot be empty or whitespace only');
  });

  test('should accept valid name and create user', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'Charlie' });

    expect(response.status).toBe(201);
    expect(response.body.message).toBe('User created successfully');
