const express = require('express');
const app = express();

// Add middleware to parse JSON request bodies
app.use(express.json());

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// POST handler for creating users with input validation
app.post('/users', (req, res) => {
  const { name } = req.body;

  // Input validation: check if name is missing or not a string
  if (name === undefined || name === null) {
    return res.status(400).json({ 
      error: 'Missing required field: name' 
    });
  }

  if (typeof name !== 'string') {
    return res.status(400).json({ 
      error: 'Invalid data type: name must be a string' 
    });
  }

  // Additional validation: check if name is empty after trimming
  if (name.trim() === '') {
    return res.status(400).json({ 
      error: 'Invalid value: name cannot be empty or whitespace only' 
    });
  }

  // If validation passes, create a new user (simulated)
  const newUser = {
    id: Math.floor(Math.random() * 1000) + 3, // Generate a new ID
    name: name.trim(),
    email: `${name.toLowerCase().replace(/\s+/g, '.')}@example.com`,
    createdAt: new Date().toISOString()
  };

  res.status(201).json({
    message: 'User created successfully',
    user: newUser
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

