{
  "name": "express-app",
  "version": "1.0.0",
  "description": "Express application with input validation",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "echo \"Error: no test specified\" && exit 1"
  },
  "dependencies": {
    "express": "^4.18.2"
  },
  "devDependencies": {
    "nodemon": "^3.0.3"
  },
  "engines": {
    "node": ">=14.0.0"
  }
}

// Test script to validate POST handler logic
const assert = require('assert');

// Simulate the validation logic from app.js
function validateName(name) {
  const errors = [];

  if (name === undefined || name === null) {
    errors.push('Missing required field: name');
  } else if (typeof name !== 'string') {
    errors.push('Field "name" must be a string');
  } else if (name.trim() === '') {
    errors.push('Field "name" cannot be empty or only whitespace');
  }

  return errors;
}

// Test cases
console.log('Running validation tests...\n');

// Test 1: Missing name
console.log('Test 1: Missing name');
const result1 = validateName(undefined);
assert.deepStrictEqual(result1, ['Missing required field: name']);
console.log('✓ Passed\n');

// Test 2: Null name
console.log('Test 2: Null name');
const result2 = validateName(null);
assert.deepStrictEqual(result2, ['Missing required field: name']);
console.log('✓ Passed\n');

// Test 3: Non-string name (number)
console.log('Test 3: Non-string name (number)');
const result3 = validateName(123);
assert.deepStrictEqual(result3, ['Field "name" must be a string']);
console.log('✓ Passed\n');

// Test 4: Non-string name (object)
console.log('Test 4: Non-string name (object)');
const result4 = validateName({});
assert.deepStrictEqual(result4, ['Field "name" must be a string']);
console.log('✓ Passed\n');

// Test 5: Empty string
console.log('Test 5: Empty string');
const result5 = validateName('');
assert.deepStrictEqual(result5, ['Field "name" cannot be empty or only whitespace']);
console.log('✓ Passed\n');

// Test 6: Whitespace only
console.log('Test 6: Whitespace only');
const result6 = validateName('   ');
assert.deepStrictEqual(result6, ['Field "name" cannot be empty or only whitespace']);
console.log('✓ Passed\n');

// Test 7: Valid name
console.log('Test 7: Valid name');
const result7 = validateName('John Doe');
assert.deepStrictEqual(result7, []);
console.log('✓ Passed\n');

// Test 8: Valid name with leading/trailing spaces
console.log('Test 8: Valid name with leading/trailing spaces');
const result8 = validateName('  Jane Smith  ');
assert.deepStrictEqual(result8, []);
console.log('✓ Passed\n');

console.log('All validation tests passed! ✅');

// Quick test to ensure server can start
const app = require('./app.js');

console.log('Server module loaded successfully');
console.log('✓ app.js exports an Express application');
console.log('✓ POST handler for /users endpoint is present');
console.log('✓ Validation middleware is configured');

